___CSS_LOADER_EXPORT___.push([module.id, `.home-screen {
  margin-left: auto;
  margin-right: auto;
  max-width: 80vw;
}

.home-screen-inactive {
  display: none;
}

.content-area {
  display: grid;
  grid-template-columns: 1.6fr 1.4fr;
  column-gap: 3vw;
  justify-content: center;
}

h1 {
  text-align: center;
  font-size: clamp(1.2rem, 2.5vw, 1.8rem);
}

.month-pill-container {
  display: flex;
  justify-content: center;
  margin-bottom: 1rem;
}

.month-pill-container::before,
.month-pill-container::after {
  content: "";
  height: 1px;
  background-color: #dbdee2;
  flex: 1;
  position: relative;
  margin-top: calc(0.675rem + 1rem);
}

body.dark-mode .month-pill-container::before,
body.dark-mode .month-pill-container::after {
  background-color: #64748b;
}

.month-pill {
  background-color: #dcf0f0;
  color: #0f766e;
  font-weight: 500;
  font-size: 0.8rem;
  padding: 0.5rem 1.7rem;
  margin: 0.675rem 0;
  border-radius: 2em;
  white-space: nowrap;
  flex-shrink: 0;
}

body.dark-mode .month-pill {
  background-color: #0a2a33;
}

.expense-details,
.total-expenditure {
  border-radius: 10px;
  background-color: #fff;
}

.left-panel {
  display: flex;
  flex-direction: column;
  gap: 1.3rem;
}

.right-panel {
  display: flex;
  flex-direction: column;
  width: 100%;
  background-color: #fff;
  box-shadow: 0px 0px 20px rgba(0, 0, 0, 0.1);
  border-radius: 10px;
}

.expense-details {
  width: 100%;
  align-self: start;
  padding: 1.5rem;
  position: relative;
  box-shadow: 0px 0px 20px rgba(0, 0, 0, 0.1);
}

.total-expenditure {
  padding: 1.5rem 2rem 1rem 2rem;
  position: relative;
}

.total-expenditure > h2 {
  text-align: center;
  margin-bottom: 0.5rem;
  font-size: clamp(1rem, 4.5vw, 1.3rem);
}

.total-expenditure::after {
  content: "";
  height: 1px;
  position: absolute;
  right: 1rem;
  left: 1rem;
  bottom: -0.1rem;
  background-color: #c8d5e7;
}

body.dark-mode .total-expenditure::after {
  background-color: #64748b;
}

body.dark-mode .expense-details,
body.dark-mode .right-panel,
body.dark-mode .total-expenditure,
body.dark-mode .recents-container {
  background-color: #031922;
}

.add-expense-button {
  width: 100%;
  margin: 20px auto 4px auto;
  padding: 9px;
  border-radius: 64px;
  border: none;
  outline: none;
  background-color: #0f766e;
  color: #f2f2f2;
  box-shadow: 0px 2px 5px rgba(0, 0, 0, 0.3);
  transition: background-color 0.3s ease opacity 0.3s ease transform 0.3s ease;
}

.add-expense-button:hover {
  cursor: pointer;
  background-color: #007269;
}

.add-expense-button:active {
  opacity: 0.9;
  transform: scale(0.99);
}

.added-to-tracker img {
  height: 20px;
}

.added-to-tracker {
  color: #06965a;
  font-size: 15px;
  display: flex;
  gap: 8px;
  align-items: center;
  justify-content: center;
  /* this will be visible once we click the add button */
  opacity: 1;
  position: absolute;
  left: 10rem;
  right: 10rem;
}

.is-added-to-tracker {
  opacity: 1;
}

.empty-field-container {
  display: flex;
  justify-content: center;
  margin-bottom: 10px;
}

.empty-field-warning {
  position: absolute;
  display: flex;
  justify-content: center;
  align-items: center;
  opacity: 1;
  color: #f44336;
}

body.dark-mode .empty-field-warning {
  color: #c03429;
}

.analysis-title {
  margin-top: 40px;
  margin-bottom: 14px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
}

.period-total {
  display: grid;
  grid-template-columns: 3fr 1fr;
  row-gap: 18px;
  column-gap: 15px;
}

.period {
  font-size: clamp(.9rem, 4.5vw, 1rem);
  font-weight: 500;
}

body.dark-mode .period {
  color: #cccbcb;
}

.cost,
.recent-expense-cost {
  font-size: clamp(.9rem, 4.5vw, 1rem);
  font-weight: 500;
  color: #3063aa;
}

body.dark-mode .cost {
  color: #2b5999;
}

.chart-container {
  margin-left: auto;
  margin-right: auto;
  max-width: clamp(250px, 50vw, 400px);
}

.recents-container {
  height: 20vh;
  padding: 1rem;
  background-color: #fff;
  margin: 0;
  width: 100%;
  box-shadow: 0px 0px 20px rgba(0, 0, 0, 0.1);
  border-radius: 0.6rem;
  overflow-y: overlay;
  display: flex;
  flex-direction: column;
  gap: 1rem;

  /* Firefox: thumb color | track color */
  scrollbar-color: rgba(88, 93, 97, 0.2) transparent;
  scrollbar-width: thin;
}

body.dark-mode .recents-container h4 {
  color: #d6d5d5;
}

/* WebKit (Chrome/Safari) */
.recents-container::-webkit-scrollbar {
  width: 8px;
}

.recents-container::-webkit-scrollbar-track {
  background: transparent; /* Makes the track blend in */
}

.recents-container::-webkit-scrollbar-thumb {
  background-color: rgba(255, 255, 255, 0.2); /* Subtle grey thumb */
  border-radius: 20px;
  border: 2px solid transparent; /* Creates a 'floating' gap */
  background-clip: content-box;
}

.recents-container::-webkit-scrollbar-thumb:hover {
  background-color: rgba(255, 255, 255, 0.3);
}

.recents-container h4 {
  text-align: center;
}

.recent-expense {
  position: relative;
}

.recent-expense:not(.recent-expense:first-of-type)::before {
  content: " ";
  height: 1px;
  background-color: #c9d8f5;
  position: absolute;
  top: -10px;
  left: 0;
  right: 0;
}

body.dark-mode .recent-expense:not(.recent-expense:first-of-type)::before {
  background-color: #4f5766;
}

body.dark-mode .recent-expense-description {
  color: #d6d5d5;
}

.recents-container .date,
.recents-container .time {
  color: #99a2b6;
  font-size: 0.9rem;
  font-weight: normal;
  display: block;
  margin-bottom: 0.2rem;
}

.recents-container .time {
  align-self: end;
}

.recents-container .date-no {
  color: #99a2b6;
}

.recent-expense-details {
  display: flex;
  flex-direction: column;
  /* justify-content: space-between; */
}

.top,
.bottom {
  display: flex;
  justify-content: space-between;
}

.recent-category {
  display: flex;
  align-items: center;
  gap: .3rem;

  color: #f2f2f2;
  font-size: 0.9rem;
  padding: 0.2rem 0.3rem;
  border-radius: 0.9rem;
}

.recent-category svg {
  stroke: #fff;
  height: 20px;
  width: 20px;
}

.recent-food-category {
  background-color: #3bb184;
}

body.dark-mode .recent-food-category {
  background-color: #206d50;
}

.recent-transport-category {
  background-color: #3a7de7;
}

body.dark-mode .recent-transport-category {
  background-color: #163f81;
}

.recent-entertainment-category {
  background-color: #9049ca;
}

body.dark-mode .recent-entertainment-category {
  background-color: #4e1979;
}

.recent-shopping-category {
  background-color: #beb41d;
}

body.dark-mode .recent-shopping-category {
  background-color: #77700b;
}

.recent-bills-category {
  background-color: #3c7eb8;
}

body.dark-mode .recent-bills-category {
  background-color: #1d578a;
}

.recent-health-category {
  background-color: #3c7ec0;
}

body.dark-mode .recent-health-category {
  background-color: #11375c;
}

.recent-other-category {
  background-color: #a55133;
}

body.dark-mode .recent-other-category {
  background-color: #7e371e;
}

.left-side {
  display: flex;
  gap: 1rem;
  align-items: center;
}

/* .right-side {
  display: flex;
  flex-direction: column;
} */

@media (min-width: 2000px) {
  .home-screen {
    max-width: 1600px;
  }
}

@media (900px < width <= 1024px) {
  .home-screen {
    max-width: 90vw;
  }
}

@media (600px < width <= 900px) {
  .home-screen {
    max-width: 70vw;
  }
}

@media (max-width: 900px) {
  .content-area {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .left-panel {
    display: contents;
  }

  .recents-container {
    order: 1;
  }
}

@media (max-width: 500px) {

  .expense-details .added-to-tracker {
    margin-top: 0px;
    margin-bottom: 0px;
  }

  .period-total .period {
    display: -webkit-box;
    -webkit-line-clamp: 1;
    line-clamp: 1;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
}

